import * as THREE from 'three';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {refineSurfaceMaterials100} from './visual-quality100.js?v=157';
let bytes;
export async function instrument142(kind){
 bytes||=(async()=>{const r=await fetch('./models/revision142/instrumentos142.glb.gz?v=143');if(!r.ok)throw Error('No se pudo cargar el instrumento');return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();})().catch(e=>{bytes=null;throw e;});
 const scene=(await new GLTFLoader().parseAsync((await bytes).slice(0),'')).scene,device=scene.getObjectByName('instrument142_'+kind);if(!device)throw Error('Instrumento incompleto');device.removeFromParent();refineSurfaceMaterials100(device);device.userData.type142=kind;return device;
}
function control(device,id,target){let source;device.traverse(o=>{if(o.userData.instrumentControl142===id)source=o;});if(!source||!target)return;target.clear();target.position.copy(source.position);target.quaternion.copy(source.quaternion);target.scale.setScalar(1);for(const c of [...source.children])target.add(c);device.add(target);source.removeFromParent();}
function screen(display,device){if(!display)return;device.add(display);display.position.set(0,.168,.122);display.rotation.set(0,0,0);display.scale.setScalar(1);for(const child of display.children){if(child.isMesh){child.rotation.set(0,0,0);child.position.set(0,0,0);child.geometry.dispose();child.geometry=new THREE.PlaneGeometry(.318,.152);}}}
export async function upgradeTechnical142(bench,id){const device=await instrument142(id==='insulation'?'megohm':'dmm'),old=bench.group.getObjectByName('Instrumento_escala139');device.position.copy(old?.position||new THREE.Vector3(.71,-.01,-.075));device.rotation.y=Math.PI;device.scale.setScalar(.65);bench.group.add(device);const display=bench.group.getObjectByName('sr129_display');control(device,'dial',bench.targets.get('dial'));control(device,'measure',bench.targets.get('measure'));const release=bench.targets.get('release');if(release){device.add(release);release.position.set(0,-.38,.12);}
 screen(display,device);for(const colour of ['red','black']){const p=bench.group.getObjectByName('sr129_'+colour+'Port');if(p){device.add(p);p.position.set(colour==='red'?.13:-.13,-.285,.125);p.rotation.set(0,0,0);p.scale.setScalar(1);}}if(old)old.visible=false;bench.instrument142=device;bench.initialiseProbes143?.(device);bench.refreshCables142?.();return bench;}
export async function upgradeService142(bench,id){const device=await instrument142(id==='ventilation'?'anemometer':'dmm'),old=bench.group.getObjectByName('sr134_meter');if(old){device.position.copy(old.position);device.quaternion.copy(old.quaternion);}device.rotation.y=Math.PI;device.scale.setScalar(.65);bench.group.add(device);screen(bench.group.getObjectByName('sr134_meterDisplay'),device);if(old)old.visible=false;bench.instrument142=device;return bench;}
export async function upgradeTrain142(rig){if(rig.id!=='electrical')return rig;const old=rig.parts.meter,device=await instrument142('dmm');device.position.copy(old.position);device.quaternion.copy(old.quaternion);device.scale.setScalar(.65);rig.group.add(device);let source;device.traverse(o=>{if(o.userData.instrumentControl142==='dial')source=o;});if(rig.parts.meterMode125){control(device,'dial',rig.parts.meterMode125);rig.selector125=rig.parts.meterMode125;rig.homes.set(rig.selector125,rig.selector125.position.clone());}
 old.visible=false;rig.parts.meter=device;rig.homes.set(device,device.position.clone());rig.pickRoots=rig.pickRoots.filter(o=>o!==old);rig.pickRoots.push(device);device.userData.handTarget='';return rig;}
